import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.CVt6dz2a.js";const m=JSON.parse('{"title":"EP.27 在别人的着色器里插一句嘴","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.27-material-patch.md","filePath":"comics/EP.27-material-patch.md","lastUpdated":1793881879000}'),r={name:"comics/EP.27-material-patch.md"};function c(l,e,i,n,h,s){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="ep-27-在别人的着色器里插一句嘴" tabindex="-1">EP.27 在别人的着色器里插一句嘴 <a class="header-anchor" href="#ep-27-在别人的着色器里插一句嘴" aria-label="Permalink to &quot;EP.27 在别人的着色器里插一句嘴&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/27-material-shader-advanced/basics">27.1 基础入门：onBeforeCompile 与材质补丁</a> 延伸阅读：<a href="./../guide/27-material-shader-advanced/advanced">27.2 进阶应用：自定义 PBR 与材质扩展架构</a> · <a href="./../guide/27-material-shader-advanced/practice">27.3 实战案例：材质预设库与运行时切换</a> 动手演示：<a href="./../public/demos/material-advanced/onbeforecompile-lab.html">onbeforecompile-lab 材质补丁台</a> · <a href="./../public/demos/material-advanced/custom-pbr-lab.html">custom-pbr-lab 自定义 PBR 对比台</a> · <a href="./../public/demos/material-advanced/material-preset-lab.html">material-preset-lab 材质预设库</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱想给产品球加一层会波动的霓虹效果，顺手写了 <code>ShaderMaterial</code>；效果是有了，可金属不再反射环境、也不吃阴影，整颗球像贴纸。标签君指出：这是&quot;另起炉灶&quot;，不是扩展。</td></tr><tr><td>② 揭秘</td><td>码叔摊开内置材质的拼装图：<code>#include &lt;begin_vertex&gt;</code>、<code>&lt;color_fragment&gt;</code>、<code>&lt;lights_fragment_end&gt;</code> 全是可以插话的窗口，<code>onBeforeCompile</code> 就在这些窗口前排队。</td></tr><tr><td>③ 实证</td><td>三个开关分别注入顶点波动、片元染色与菲涅尔边缘光，draw call 与程序数纹丝不动——补丁没有新建材质，只是让原着色器多说了一句话。</td></tr><tr><td>④ 结案</td><td>四条纪律写进规范：差异做成 uniform、缓存键写版本号、补丁贴着 include、影子另配深度材质。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-另起炉灶的代价-pbr-不是白送的" tabindex="-1">① 另起炉灶的代价：PBR 不是白送的 <a class="header-anchor" href="#_1-另起炉灶的代价-pbr-不是白送的" aria-label="Permalink to &quot;① 另起炉灶的代价：PBR 不是白送的&quot;">​</a></h3><p><code>ShaderMaterial</code> 只拿到你写的那几行 GLSL。内置材质的 IBL 反射、灯光循环、阴影采样、雾效、色调映射、输出编码，全都在你没写的地方。所以&quot;全息效果做出来了，但球不像产品了&quot;，不是效果不够好，而是<strong>整条管线被绕过了</strong>。要保留 PBR，就得在它的流程里做加法，而不是重写它。</p><h3 id="_2-内置-shader-是拼装出来的" tabindex="-1">② 内置 shader 是拼装出来的 <a class="header-anchor" href="#_2-内置-shader-是拼装出来的" aria-label="Permalink to &quot;② 内置 shader 是拼装出来的&quot;">​</a></h3><p><code>MeshStandardMaterial</code> / <code>MeshPhysicalMaterial</code> 的源码由几十个 chunk 拼成。<code>onBeforeCompile(shader, renderer)</code> 在 include 展开<strong>之前</strong>被调用，所以你能拿到带占位符的完整字符串，再用 <code>replace</code> 把代码插进指定窗口：</p><table tabindex="0"><thead><tr><th>注入点</th><th>阶段</th><th>能做什么</th></tr></thead><tbody><tr><td><code>begin_vertex</code></td><td>顶点</td><td>顶点波动、风摆、形变</td></tr><tr><td><code>color_fragment</code></td><td>片元·基础色</td><td>染色、图案、贴图混合</td></tr><tr><td><code>lights_fragment_end</code></td><td>片元·光照后</td><td>边缘光、sheen、自定义高光项</td></tr><tr><td><code>dithering_fragment</code></td><td>片元·输出前</td><td>屏幕空间噪点、暗角</td></tr></tbody></table><p>注入点越靠后，越像&quot;在成片上加滤镜&quot;；越靠前，越容易被后续步骤覆盖。选点比写公式更重要。</p><h3 id="_3-补丁不产生新的绘制批次" tabindex="-1">③ 补丁不产生新的绘制批次 <a class="header-anchor" href="#_3-补丁不产生新的绘制批次" aria-label="Permalink to &quot;③ 补丁不产生新的绘制批次&quot;">​</a></h3><p>拨动三个开关时，<code>draw calls</code> 始终是&quot;两颗球 + 地面&quot;的 3，<code>program</code> 数也不增加。因为补丁只改了同一份 shader 的文本，没有新建材质、没有新建物体。<strong>补丁的价值就在于此：用一份材质的能力，做三份材质的活。</strong></p><h3 id="_4-缓存键与-uniform-补丁系统的两条命门" tabindex="-1">④ 缓存键与 uniform：补丁系统的两条命门 <a class="header-anchor" href="#_4-缓存键与-uniform-补丁系统的两条命门" aria-label="Permalink to &quot;④ 缓存键与 uniform：补丁系统的两条命门&quot;">​</a></h3><ul><li>默认缓存键取 <code>onBeforeCompile.toString()</code>，闭包里的数值不在其中；两个&quot;源码相同、参数不同&quot;的补丁会撞键，表现为&quot;改一个，全部跟着变&quot;。</li><li>修法有两种：把差异拼进 <code>customProgramCacheKey</code>，或干脆把差异做成 uniform、让 GLSL 文本永远一致（推荐后者）。</li><li>uniform 对象要放在材质外、由钩子挂载。重新编译时钩子会再跑一次，内部 <code>new</code> 出来的引用会失效。</li><li>改 <code>uniform.value</code> 不需要 <code>needsUpdate</code>；只有改 GLSL 文本、改宏、改影响 shader 结构的属性才需要。</li></ul><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：补丁写了，画面没反应？</strong> 先确认 <code>onBeforeCompile</code> 真的被调用，再确认 <code>replace</code> 的目标字符串存在——匹配不到时它不会报错。</li><li><strong>Q：只改一个物体，其他物体也变了？</strong> <code>customProgramCacheKey</code> 撞车，复用到了同一份已编译程序。</li><li><strong>Q：拖滑条就卡一下？</strong> 在回调里调了 <code>needsUpdate</code>，触发重新编译。改 uniform 不需要它。</li><li><strong>Q：球在动，影子不动？</strong> 阴影走 <code>customDepthMaterial</code>，补丁要再给深度材质补一份顶点逻辑。</li><li><strong>Q：升级 Three.js 后补丁失效？</strong> chunk 名称或内部实现变了。补丁要贴着官方 include 写，并在版本升级时跑一次回归。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li><code>onBeforeCompile</code> 在 include 展开之前还是之后被调用？这个时序为什么决定了&quot;字符串替换&quot;是可行的注入方式？</li><li>默认的 <code>customProgramCacheKey</code> 为什么会让两个不同补丁复用同一份程序？你打算怎么修？</li><li>顶点补丁让球体动了，但影子没动。缺失的是哪一份材质？怎么补？</li></ol><details><summary>答案</summary><ol><li>在 include 展开之前。此时 <code>shader.vertexShader</code> / <code>shader.fragmentShader</code> 里仍是 <code>#include &lt;begin_vertex&gt;</code> 这样的占位符，所以可以用 <code>replace</code> 精确地在占位符位置插入自己的代码；如果等展开之后再拿到字符串，注入点就被淹没在大段实现里了。</li><li>默认键取 <code>onBeforeCompile.toString()</code>，只包含函数源码，不包含闭包捕获的数值。两个源码相同、只是插入了不同颜色/参数的补丁会得到同一个键。修法：把区分字段拼进 <code>customProgramCacheKey</code>，或把差异做成 uniform、让 GLSL 文本保持一致，键只保留版本号。</li><li>缺的是 <code>customDepthMaterial</code>（点光源场景是 <code>customDistanceMaterial</code>）。阴影渲染用的是 <code>MeshDepthMaterial</code>，不会执行表面材质里的补丁。补法：新建一个 <code>MeshDepthMaterial</code>，用同样的顶点注入逻辑，赋给 <code>mesh.customDepthMaterial</code>。</li></ol></details>',20)])])}const p=t(r,[["render",c]]);export{m as __pageData,p as default};
